const inputItems = $input.all();

function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).replace(/\s+/g, ' ').trim();
}

function normalizeText(value) {
  return clean(value)
    .toLowerCase()
    .replace(/ß/g, 'ss')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[’'`´]/g, '')
    .replace(/&/g, ' und ')
    .replace(/[^a-z0-9äöüÄÖÜ\s-]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function getField(row, names) {
  for (const name of names) {
    if (row[name] !== undefined && row[name] !== null && clean(row[name]) !== '') {
      return row[name];
    }
  }

  const rowKeys = Object.keys(row);
  for (const name of names) {
    const wanted = normalizeText(name);
    const foundKey = rowKeys.find(k => normalizeText(k) === wanted);
    if (foundKey && clean(row[foundKey]) !== '') {
      return row[foundKey];
    }
  }

  return '';
}

function normalizeUrl(value) {
  let url = clean(value);

  if (!url) return '';

  if (url.startsWith('www.')) {
    url = `https://${url}`;
  }

  if (!/^https?:\/\//i.test(url)) {
    return '';
  }

  return url;
}

function formatIsoDate(date) {
  return date.toISOString().slice(0, 10);
}

function todayIsoEuropeBerlin() {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(new Date());

  const map = {};
  for (const part of parts) {
    map[part.type] = part.value;
  }

  return `${map.year}-${map.month}-${map.day}`;
}

function addMonthsIso(isoDate, months) {
  const [year, month, day] = isoDate.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  date.setUTCMonth(date.getUTCMonth() + months);
  return formatIsoDate(date);
}

function parseIsoDate(value) {
  const text = clean(value);
  const match = text.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (!match) return null;
  return `${match[1]}-${match[2]}-${match[3]}`;
}

function parseGermanDate(value) {
  const text = clean(value);
  const match = text.match(/(\d{1,2})\.(\d{1,2})\.(\d{2,4})/);
  if (!match) return null;

  const day = String(match[1]).padStart(2, '0');
  const month = String(match[2]).padStart(2, '0');
  let year = String(match[3]);

  if (year.length === 2) {
    year = `20${year}`;
  }

  return `${year}-${month}-${day}`;
}

function extractDateRange(value) {
  const text = clean(value);

  const isoMatches = [...text.matchAll(/(\d{4})-(\d{2})-(\d{2})/g)];
  if (isoMatches.length > 0) {
    return {
      start: `${isoMatches[0][1]}-${isoMatches[0][2]}-${isoMatches[0][3]}`,
      end: isoMatches.length > 1
        ? `${isoMatches[1][1]}-${isoMatches[1][2]}-${isoMatches[1][3]}`
        : null,
    };
  }

  const germanMatches = [...text.matchAll(/(\d{1,2})\.(\d{1,2})\.(\d{2,4})/g)];
  if (germanMatches.length > 0) {
    return {
      start: parseGermanDate(germanMatches[0][0]),
      end: germanMatches.length > 1 ? parseGermanDate(germanMatches[1][0]) : null,
    };
  }

  return { start: null, end: null };
}

function parseDateFromEventId(eventId) {
  const match = clean(eventId).match(/^(\d{4}-\d{2}-\d{2})/);
  return match ? match[1] : null;
}

function parseTimeFromEventId(eventId) {
  const match = clean(eventId).match(/^\d{4}-\d{2}-\d{2}[_\s-]+(\d{2}:\d{2})/);
  return match ? match[1] : null;
}

function parseTimes(value) {
  const text = clean(value)
    .replace(/[–—]/g, '-')
    .replace(/Uhr/gi, '')
    .replace(/\s+/g, ' ')
    .trim();

  const matches = [...text.matchAll(/(\d{1,2})[:.](\d{2})/g)]
    .map(m => `${String(m[1]).padStart(2, '0')}:${m[2]}`);

  return {
    start: matches[0] || null,
    end: matches[1] || null,
  };
}

function formatGermanDate(isoDate) {
  if (!isoDate) return '';
  const [year, month, day] = isoDate.split('-');
  return `${day}.${month}.${year}`;
}

function makeSlug(value) {
  return normalizeText(value)
    .replace(/\s+/g, '_')
    .replace(/-+/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_|_$/g, '')
    .slice(0, 90);
}

