function inferSourceId(row) {
  const explicit = clean(getField(row, ['source_id', 'sourceId', 'Source ID']));
  if (explicit) return makeSlug(explicit);

  const haystack = normalizeText([
    getField(row, ['Quelle', 'source_name', 'sourceName']),
    getField(row, ['URL', 'url', 'source_url', 'sourceUrl']),
    getField(row, ['Veranstalter', 'organizer']),
    getField(row, ['Veranstaltungsort', 'venue']),
    getField(row, ['event_id', 'Event ID']),
  ].join(' '));

  const found = SOURCE_DEFAULTS.find(source =>
    source.match.some(term => haystack.includes(normalizeText(term)))
  );

  return found ? found.source_id : '';
}

function getSourceDefaults(row, sourceId) {
  const haystack = normalizeText([
    sourceId,
    getField(row, ['Quelle', 'source_name', 'sourceName']),
    getField(row, ['URL', 'url', 'source_url', 'sourceUrl']),
    getField(row, ['Veranstalter', 'organizer']),
    getField(row, ['Veranstaltungsort', 'venue']),
    getField(row, ['event_id', 'Event ID']),
  ].join(' '));

  return SOURCE_DEFAULTS.find(source =>
    source.match.some(term => haystack.includes(normalizeText(term)))
  ) || null;
}

function normalizeCategory(rawCategory, title, description, sourceId) {
  const raw = normalizeText(rawCategory);
  const text = normalizeText(`${title} ${description}`);
  const sid = normalizeText(sourceId);

  if (sid.includes('mot_treff_kotten')) {
    if (text.includes('musik') || text.includes('lagerfeuer') || text.includes('dusty trails') || text.includes('bloody')) {
      return 'Musik / Motorsport / Stadtteil';
    }
    if (text.includes('korso') || text.includes('ausfahrt') || text.includes('o fahrt') || text.includes('geo caching')) {
      return 'Motorsport / Ausfahrt';
    }
    if (text.includes('sicherheit') || text.includes('erste hilfe') || text.includes('technik')) {
      return 'Workshop / Sicherheit / Motorsport';
    }
    if (text.includes('trial')) {
      return 'Trial / Motorsport';
    }
    if (text.includes('fruehstueck') || text.includes('frühstück') || text.includes('mittagessen')) {
      return 'Verpflegung / Motorsport';
    }
    return 'Jugend / Motorsport / Stadtteil';
  }

  if (!raw) {
    if (text.includes('konzert') || text.includes('musik')) return 'Musik / Konzert';
    if (text.includes('workshop')) return 'Workshop / Kurs';
    if (text.includes('seminar')) return 'Seminar / Bildung';
    if (text.includes('theater')) return 'Theater / Kultur';
    return 'Veranstaltung';
  }

  const directMappings = [
    { keys: ['performance', 'musik', 'music', 'live musik'], value: 'Musik / Kultur' },
    { keys: ['concert', 'konzert'], value: 'Musik / Konzert' },
    { keys: ['workshop', 'kurs'], value: 'Workshop / Kurs' },
    { keys: ['seminar'], value: 'Seminar / Bildung' },
    { keys: ['civic activity', 'civic'], value: 'Stadtteil / Begegnung' },
    { keys: ['cultural activity', 'cultural'], value: 'Kultur / Stadtteil' },
    { keys: ['cultural festival', 'festival'], value: 'Kulturfestival / Stadtteil' },
    { keys: ['theaterstuck', 'theaterstück', 'theatre', 'theater'], value: 'Theater / Kultur / Kinderkultur' },
    { keys: ['dance', 'tanz'], value: 'Tanz / Kultur' },
    { keys: ['lesung', 'vorlese'], value: 'Lesung / Kultur' },
    { keys: ['beratung'], value: 'Stadtteil / Begegnung / Beratung' },
    { keys: ['bildung'], value: 'Bildung / Stadtteil' },
  ];

  const found = directMappings.find(mapping =>
    mapping.keys.some(key => raw.includes(normalizeText(key)))
  );

  if (found) return found.value;

  return clean(rawCategory);
}

function canonicalTitle(title, description) {
  const text = normalizeText(`${title} ${description}`);

  if (
    text.includes('vorlese cafe') &&
    (
      text.includes('chinesisch') ||
      text.includes('deutsch') ||
      text.includes('huang') ||
      text.includes('sohnes grosse puppe') ||
      text.includes('mai')
    )
  ) {
    return 'vorlese_cafe_chinesisch_deutsch';
  }

  if (text.includes('coerdinale')) {
    return 'coerdinale';
  }

  return normalizeText(title)
    .replace(/\bjeden\b/g, '')
    .replace(/\bfreitag\b/g, '')
    .replace(/\bsamstag\b/g, '')
    .replace(/\bsonntag\b/g, '')
    .replace(/\bopen class\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeOrganizer(value) {
  return normalizeText(value)
    .replace(/\bev\b/g, '')
    .replace(/\be v\b/g, '')
    .replace(/\bgmbh\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function dedupeKey(row) {
  const titleKey = canonicalTitle(row.Titel, row.Kurzbeschreibung);
  const organizerKey = normalizeOrganizer(row.Veranstalter);
  const venueKey = normalizeText(row.Veranstaltungsort || row.Adresse || row.Ort);

  return [
    row.date_start,
    row.time_start || '',
    titleKey,
    organizerKey || venueKey,
  ].join('|');
}

function hasGermanCategory(category) {
  const value = clean(category);
  if (!value) return false;
  return /[äöüÄÖÜ]|\s\/\s|Kultur|Stadtteil|Theater|Musik|Beratung|Bildung|Workshop|Seminar|Konzert|Lesung|Tanz|Motorsport/.test(value);
}

function rowScore(row) {
  let score = 0;

  if (row.URL) score += 20;
  if (row.Quelle) score += 8;
  if (hasGermanCategory(row.Kategorie)) score += 6;
  if (row.Kurzbeschreibung) score += Math.min(row.Kurzbeschreibung.length / 40, 8);
  if (row.Veranstaltungsort) score += 3;
  if (row.Adresse) score += 2;
  if (row.Veranstalter) score += 2;

  const url = normalizeText(row.URL);
  if (url.includes('kultur-coerde')) score += 3;
  if (url.includes('stadt-muenster')) score += 2;
  if (url.includes('awo-msl-re')) score += 2;

  return score;
}

function buildNormalizedRow(row) {
  const sourceId = inferSourceId(row);
  const defaults = getSourceDefaults(row, sourceId);

  const eventIdRaw = clean(getField(row, ['event_id', 'Event ID', 'id']));

  const dateStartRaw = getField(row, ['date_start', 'dateStart', 'Date Start']);
  const dateEndRaw = getField(row, ['date_end', 'dateEnd', 'Date End']);
  const datumRaw = getField(row, ['Datum', 'date', 'datum']);

  const dateRangeFromDatum = extractDateRange(datumRaw);

  const date_start =
    parseIsoDate(dateStartRaw) ||
    parseGermanDate(dateStartRaw) ||
    dateRangeFromDatum.start ||
    parseDateFromEventId(eventIdRaw);

  const date_end =
    parseIsoDate(dateEndRaw) ||
    parseGermanDate(dateEndRaw) ||
    dateRangeFromDatum.end ||
    date_start;

  const timeRaw = getField(row, ['Uhrzeit', 'time', 'Time']);
  const times = parseTimes(timeRaw);

  const time_start =
    clean(getField(row, ['time_start', 'timeStart', 'Time Start'])) ||
    times.start ||
    parseTimeFromEventId(eventIdRaw) ||
    null;

  const time_end =
    clean(getField(row, ['time_end', 'timeEnd', 'Time End'])) ||
    times.end ||
    null;

  const title = clean(getField(row, ['Titel', 'title', 'Title']));
  const description = clean(getField(row, ['Kurzbeschreibung', 'description_short', 'descriptionShort', 'Description']));

  let url =
    normalizeUrl(getField(row, ['URL', 'url', 'source_url', 'sourceUrl'])) ||
    (defaults ? defaults.url : '');

  let sourceName =
    clean(getField(row, ['Quelle', 'source_name', 'sourceName', 'Source Name'])) ||
    (defaults ? defaults.source_name : '');

  let venue =
    clean(getField(row, ['Veranstaltungsort', 'venue', 'Venue'])) ||
    (defaults && defaults.venue ? defaults.venue : '');

  let address =
    clean(getField(row, ['Adresse', 'address', 'Address'])) ||
    (defaults && defaults.address ? defaults.address : '');

  if (
    defaults &&
    defaults.address &&
    address &&
    normalizeText(defaults.address).startsWith(normalizeText(address)) &&
    defaults.address.length > address.length
  ) {
    address = defaults.address;
  }

  let city =
    clean(getField(row, ['Ort', 'city', 'City'])) ||
    (defaults && defaults.city ? defaults.city : '');

  let organizer =
    clean(getField(row, ['Veranstalter', 'organizer', 'Organizer'])) ||
    (defaults && defaults.organizer ? defaults.organizer : '');

  let categoryRaw =
    clean(getField(row, ['Kategorie', 'category', 'Category'])) ||
    (defaults && defaults.category ? defaults.category : '');

  const category = normalizeCategory(categoryRaw, title, description, sourceId);

  let confidenceRaw = clean(getField(row, ['confidence', 'Confidence', 'Konfidenz']));
  confidenceRaw = confidenceRaw.replace(',', '.');
  const confidence = Number.isFinite(Number(confidenceRaw)) ? Number(confidenceRaw) : 0.9;

  const notes = clean(getField(row, [
    'Hinweise_Prüfstatus',
    'Hinweise',
    'extraction_notes',
    'notes',
  ]));

  const event_id = eventIdRaw || [
    date_start,
    time_start || '00:00',
    makeSlug(title),
    sourceId || makeSlug(sourceName),
  ].filter(Boolean).join('_');

  const sort_key = `${date_start || '9999-12-31'} ${time_start || '00:00'}`;

  const datum =
    date_start && date_end && date_start !== date_end
      ? `${formatGermanDate(date_start)}–${formatGermanDate(date_end)}`
      : formatGermanDate(date_start);

  const uhrzeit =
    time_start && time_end
      ? `${time_start}–${time_end}`
      : (time_start || '');

  return {
    event_id,
    sort_key,
    Datum: datum,
    Uhrzeit: uhrzeit,
    Titel: title,
    Veranstaltungsort: venue,
    Adresse: address,
    Ort: city,
    Veranstalter: organizer,
    Kategorie: category,
    Kurzbeschreibung: description,
    Quelle: sourceName,
    URL: url,
    confidence,
    Hinweise_Prüfstatus: notes,
    publish: clean(getField(row, ['publish', 'Publish'])),
    date_start,
    date_end,
    time_start,
    time_end,
    source_id: sourceId || (defaults ? defaults.source_id : ''),
  };
}

const todayIso = todayIsoEuropeBerlin();
// Keine Obergrenze mehr – siehe Kopfkommentar. Die 6-Monats-Grenze für
// Serientermine setzt „Serientermine kennzeichnen“.

const normalizedRows = [];

for (const item of inputItems) {
  const row = item.json || {};
  const publishValue = normalizeText(getField(row, ['publish', 'Publish']));

  if (['nein', 'no', 'false', '0', 'n'].includes(publishValue)) {
    continue;
  }

  const normalized = buildNormalizedRow(row);

  if (!normalized.Titel || !normalized.date_start) {
    continue;
  }

  const endDate = normalized.date_end || normalized.date_start;

  if (endDate < todayIso) {
    continue;
  }

  normalizedRows.push(normalized);
}

const deduped = new Map();

for (const row of normalizedRows) {
  const key = dedupeKey(row);

  if (!deduped.has(key)) {
    deduped.set(key, row);
    continue;
  }

  const existing = deduped.get(key);
  if (rowScore(row) > rowScore(existing)) {
    deduped.set(key, row);
  }
}

const outputRows = [...deduped.values()]
  .sort((a, b) => {
